<div class="heading"><div><h1>هنرمندان نامیرا</h1><p class="muted">پدیدآورندگان آثار ماندگار شهدا</p></div><span><?= fa($result['count']) ?> هنرمند</span></div>
<form class="panel public-artist-search" method="get"><input type="hidden" name="page" value="artists"><label>جست‌وجوی هنرمند<input name="q" value="<?= e($_GET['q']??'') ?>" placeholder="نام هنرمند"></label><label>تخصص<select name="specialty"><option value="">همه رشته‌ها</option><?php foreach($specialties as $term): ?><option value="<?= $term['id'] ?>" <?= (int)($_GET['specialty']??0)===(int)$term['id']?'selected':'' ?>><?= e($term['title']) ?></option><?php endforeach ?></select></label><button class="primary">جست‌وجو</button></form>
<div class="artist-grid"><?php $termLabels=array_column($specialties,'title','id');foreach($result['items'] as $a):$location=array_filter([$a['data']['province']??'',$a['data']['county']??'',$a['data']['city']??''],fn($x)=>Namira\PublicPresentation::meaningful($x));$skills=array_values(array_intersect_key($termLabels,array_flip($a['data']['specialties']??[]))); ?><article class="panel artist-card"><a class="artist-card-heading" href="<?= e(url('artist',['id'=>$a['id']])) ?>"><?php view('artist-avatar',['artist'=>$a]); ?><h2><?= e($a['display_name']) ?></h2></a><?php if($location): ?><p class="muted"><?= e(implode('، ',array_unique($location))) ?></p><?php endif ?><?php if($skills): ?><p><?= e(implode('، ',$skills)) ?></p><?php endif ?><span class="artist-work-count"><?= fa($a['work_count']) ?> اثر</span><a class="outline" href="<?= e(url('artist',['id'=>$a['id']])) ?>">پروفایل و آثار ←</a></article><?php endforeach ?></div>
<?php if(!$result['items']): ?><section class="panel"><p>هنرمندی مطابق جست‌وجو منتشر نشده است.</p></section><?php endif ?>
